<?php
require_once __DIR__ . '/../config/database.php';
require_once __DIR__ . '/../includes/functions.php';
requireRole(['organizer']);
$organizerId = (int)getCurrentUserId();
$eventId = max(0, (int)($_GET['event_id'] ?? 0));
$events = fetchAll('SELECT event_id, event_name FROM Events_007 WHERE organizer_id = ? ORDER BY event_date DESC', [$organizerId]);
$page = max(1, (int)($_GET['page'] ?? 1));
$limit = 50;
$offset = ($page - 1) * $limit;
$transactions = fetchAll("SELECT p.transaction_reference, p.status AS payment_status, p.created_at, b.booking_reference, b.status AS booking_status,
    b.gross_minor, b.commission_minor, b.gateway_fee_minor, b.organizer_net_minor, e.event_name, a.full_name AS attendee_name, a.email
    FROM MarketplacePayments_007 p JOIN BookingOrders_007 b ON b.booking_id = p.booking_id
    JOIN Events_007 e ON e.event_id = b.event_id JOIN Attendees_007 a ON a.attendee_id = b.attendee_id
    WHERE b.organizer_id = ? AND (? = 0 OR b.event_id = ?) ORDER BY p.created_at DESC LIMIT $limit OFFSET $offset", [$organizerId, $eventId, $eventId]);
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Transactions</title><link href="../assets/css/style.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.9/dist/css/bootstrap.min.css" rel="stylesheet"></head><body><?php include __DIR__ . '/../includes/header.php'; ?><main class="container-fluid py-4"><div class="d-flex justify-content-between"><h1 class="h2">Online transactions</h1><a class="btn btn-outline-primary" href="payment_account.php">Settlement account</a></div><form class="my-3"><label class="form-label" for="event_id">Filter by event</label><select class="form-select" style="max-width:440px" name="event_id" id="event_id" onchange="this.form.submit()"><option value="0">All my events</option><?php foreach ($events as $event): ?><option value="<?php echo (int)$event['event_id']; ?>" <?php echo $eventId === (int)$event['event_id'] ? 'selected' : ''; ?>><?php echo htmlspecialchars($event['event_name']); ?></option><?php endforeach; ?></select></form><div class="table-responsive"><table class="table table-sm align-middle"><thead><tr><th>Date</th><th>Event / Booking</th><th>Attendee</th><th>Status</th><th>Gross</th><th>Commission</th><th>Gateway fee</th><th>Organizer allocation</th></tr></thead><tbody><?php foreach ($transactions as $tx): ?><tr><td><?php echo htmlspecialchars($tx['created_at']); ?></td><td><?php echo htmlspecialchars($tx['event_name'] . ' / ' . $tx['booking_reference']); ?><br><small><?php echo htmlspecialchars($tx['transaction_reference']); ?></small></td><td><?php echo htmlspecialchars($tx['attendee_name'] . ' (' . $tx['email'] . ')'); ?></td><td><?php echo htmlspecialchars($tx['payment_status'] . ' / ' . $tx['booking_status']); ?></td><td>GHS <?php echo number_format(((int)$tx['gross_minor']) / 100, 2); ?></td><td>GHS <?php echo number_format(((int)$tx['commission_minor']) / 100, 2); ?></td><td><?php echo $tx['gateway_fee_minor'] === null ? 'Pending' : 'GHS ' . number_format(((int)$tx['gateway_fee_minor']) / 100, 2); ?></td><td><?php echo $tx['organizer_net_minor'] === null ? 'Pending' : 'GHS ' . number_format(((int)$tx['organizer_net_minor']) / 100, 2); ?></td></tr><?php endforeach; ?><?php if (!$transactions): ?><tr><td colspan="8" class="text-muted">No online transactions for this event.</td></tr><?php endif; ?></tbody></table></div><p class="small text-muted">Allocation is not confirmation of settlement receipt. This page is limited to the signed-in organizer's events.</p></main><?php include __DIR__ . '/../includes/footer.php'; ?></body></html>
